<script>
const api=<?= json_encode(reforma_tributaria_url('configuracoes-fiscais.php'),JSON_UNESCAPED_SLASHES) ?>;const pageSize=50;let type=<?= json_encode($initial) ?>,filter='all',query='',page=1;const out=document.querySelector('#result'),sum=document.querySelector('#summary'),esc=x=>String(x??'').replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]));
function url(extra){return api+'?'+new URLSearchParams(Object.assign({tipo:type,filtro:filter,busca:query,pagina:page,por_pagina:pageSize},extra||{}))}
function summary(data){if(!data.available){sum.innerHTML='<p class="message">'+esc(data.message||'Consulta indisponível.')+'</p>';return}const x=data[type]||{};sum.innerHTML='<article><b>'+esc(x.total||0)+'</b><span>'+type.toUpperCase()+' cadastrado</span></article><article><b>'+esc(x.configured||0)+'</b><span>Configurados</span></article><article><b>'+esc(x.pending||0)+'</b><span>Sem configuração</span></article>'}
function openModal(modal){document.documentElement.classList.add('modal-open');document.body.classList.add('modal-open');modal.showModal()}function closeModal(modal){modal.close();document.documentElement.classList.remove('modal-open');document.body.classList.remove('modal-open')}function detailCard(detail){const unfilled=detail.value==='Não informado';return '<article class="record-detail'+(unfilled?' record-detail--unfilled':'')+'"><b>'+esc(detail.label)+'</b><span>'+esc(detail.value)+'</span></article>'}function detailSection(title,details){return details.length?'<section class="detail-section"><h3 class="detail-section__title">'+esc(title)+'</h3><div class="detail-section__grid">'+details.map(detailCard).join('')+'</div></section>':''}function showRecord(record){const byLabel={};record.details.forEach(detail=>byLabel[detail.label]=detail);const get=labels=>labels.map(label=>byLabel[label]).filter(Boolean);const classification=get(['Situação tributária CBS/IBS','Classificação tributária CBS/IBS','CST CBS/IBS regular','Classificação tributária regular']);const composition=get(['Débito/crédito CBS','Débito/crédito IBS','Não somar IBS/CBS no total da reforma']);const deductions=record.details.filter(detail=>detail.label.indexOf('Deduzir ')===0);const rateGroups=[['CBS',['Alíquota CBS','Redução CBS','Diferimento CBS']],['IBS UF',['Alíquota IBS UF','Redução IBS UF','Diferimento IBS UF']],['IBS municipal',['Alíquota IBS municipal','Redução IBS municipal','Diferimento IBS municipal']]].map(([title,labels])=>{const values=get(labels);return values.length?'<article class="rate-group"><h4>'+esc(title)+'</h4>'+values.map(detail=>'<div><span>'+esc(detail.label.replace(/^(Alíquota|Redução|Diferimento) /,''))+'</span><b>'+esc(detail.value)+'</b></div>').join('')+'</article>':''}).join('');document.querySelector('#record-title').textContent='Detalhes de '+record.code;document.querySelector('#record-subtitle').textContent=record.description;document.querySelector('#record-details').innerHTML=detailSection('Classificação da operação',classification)+detailSection('Crédito e composição do total',composition)+detailSection('Deduções da base',deductions)+(rateGroups?'<section class="detail-section"><h3 class="detail-section__title">Alíquotas e ajustes</h3><div class="rate-groups">'+rateGroups+'</div></section>':'');openModal(document.querySelector('#record-dialog'))}function valueCell(value){return '<td class="config-value'+(value==='—'||value==='Não informado'?' muted-value':'')+'">'+esc(value)+'</td>'}function pageList(totalPages){const pages=[];for(let current=1;current<=totalPages;current++){if(current===1||current===totalPages||Math.abs(current-page)<=1)pages.push(current)}return pages.filter((current,index)=>index===0||current!==pages[index-1]).map((current,index,all)=>(index&&current>all[index-1]+1?'<i>…</i>':'')+'<button data-page="'+current+'" type="button"'+(current===page?' aria-current="page"':'')+'>'+current+'</button>').join('')}function draw(data){if(!data.available){out.innerHTML='<p class="message">'+esc(data.message||'Consulta indisponível.')+'</p>';return}const rows=data.records||[],total=Number(data.total||0),totalPages=Math.max(1,Math.ceil(total/pageSize));if(page>totalPages){page=totalPages;load();return}if(!rows.length){out.innerHTML='<p class="message">Nenhum cadastro encontrado para os filtros informados.</p>';return}const idLabel=type==='cfop'?'ID CFOP':'ID NCM',start=(page-1)*pageSize+1,end=Math.min(page*pageSize,total);let html='<div class="grid-scroll"><table><thead><tr><th>'+idLabel+'</th><th>Código</th><th>Descrição</th><th>Situação</th><th>CST</th><th>Classif.</th><th>CST reg.</th><th>Classif. reg.</th><th>Detalhes</th></tr></thead><tbody>';rows.forEach((r,index)=>{html+='<tr><td class="config-value">'+esc(r.id)+'</td><td><b>'+esc(r.code)+'</b></td><td>'+esc(r.description)+'</td><td><span class="badge '+(r.filter==='configured'?'ok':'pending')+'">'+esc(r.status)+'</span></td>'+valueCell(r.cst)+valueCell(r.classification)+valueCell(r.regular_cst)+valueCell(r.regular_classification)+'<td><button class="record-open" data-record="'+index+'" type="button">Ver detalhes</button></td></tr>'});html+='</tbody></table></div><nav class="pagination" aria-label="Paginação"><span>Exibindo '+start+'–'+end+' de '+total+' registros</span><button data-page="'+(page-1)+'" type="button"'+(page===1?' disabled':'')+'>Anterior</button>'+pageList(totalPages)+'<button data-page="'+(page+1)+'" type="button"'+(page===totalPages?' disabled':'')+'>Próxima</button></nav>';out.innerHTML=html;out.querySelectorAll('[data-record]').forEach(button=>button.onclick=()=>showRecord(rows[Number(button.dataset.record)]));out.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>{page=Number(button.dataset.page);load();out.scrollIntoView({block:'start',behavior:'smooth'})})}
function load(){document.querySelectorAll('[data-type]').forEach(b=>b.classList.toggle('active',b.dataset.type===type));document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));document.querySelector('#csv').href=url({exportar:'csv',por_pagina:0});fetch(api,{credentials:'same-origin'}).then(r=>r.json()).then(summary);fetch(url(),{credentials:'same-origin'}).then(r=>r.json()).then(draw).catch(()=>out.innerHTML='<p class="message">Não foi possível consultar as configurações agora.</p>')}
document.querySelectorAll('button[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;filter='all';page=1;load()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;page=1;load()});let timer;document.querySelector('#query').oninput=e=>{clearTimeout(timer);timer=setTimeout(()=>{query=e.target.value;page=1;load()},250)};document.querySelector('#guide').onclick=()=>{const cfop=type==='cfop';document.querySelector('#path').textContent=cfop?'Fiscal → CFOP → aba Reforma':'Fiscal → NCM → Cadastro NCM – Vale para todas empresas → aba Reforma';document.querySelector('#image').src=cfop?'assets/guia-configuracoes-fiscais-cfop.png':'assets/guia-configuracoes-fiscais-ncm.png';openModal(document.querySelector('#dialog'))};document.querySelector('#record-close').onclick=()=>closeModal(document.querySelector('#record-dialog'));document.querySelectorAll('dialog').forEach(modal=>modal.addEventListener('close',()=>{if(!document.querySelector('dialog[open]')){document.documentElement.classList.remove('modal-open');document.body.classList.remove('modal-open')}}));load();
</script>
